import logoSizes from "@/public/logos/sizes.json";

export type Firm = {
  name: string;
  /** PNG under /public/logos; run scripts/prepare-logos.py after adding one */
  logo: string;
};

/**
 * Display size per logo file, generated by scripts/prepare-logos.py so every
 * logo carries roughly the same visual weight.
 */
export function logoSize(firm: Firm) {
  return (logoSizes as Record<string, { w: number; h: number }>)[firm.logo] ?? { w: 135, h: 54 };
}

